<script setup>
import {ref,onMounted} from 'vue'
import ContactForm from '../../../shared/ContactForm.vue'
import {defaultForm,formFieldTypes,deliveryStates} from '../../../shared/forms.js'
const props=defineProps({apiWrite:Function})
const tab=ref('forms'),forms=ref([]),settings=ref(null),draft=ref(null),preview=ref(false),messages=ref({rows:[],total:0,page:1}),message=ref(null),status=ref(''),busy=ref(false),error=ref(''),notice=ref(''),toText=ref(''),smtpPassword=ref(''),botToken=ref(''),clearPassword=ref(false),clearToken=ref(false),retryAck=ref(false)
const messageStates={new:'Новое',read:'Прочитано',closed:'Обработано'}
const failures={CREDENTIALS_UNREADABLE:'Старые секреты не расшифрованы. Сохраните новые параметры и повторите с текущими настройками.',SMTP_CONNECTION_FAILED:'Нет соединения: проверьте сервер, порт, DNS и доступ с VDS.',SMTP_AUTH_REJECTED:'Сервер отклонил вход: проверьте логин и пароль приложения.',SMTP_ADDRESS_REJECTED:'SMTP разрешён только по публичному IPv4-адресу.',SMTP_REJECTED:'SMTP отклонил письмо: проверьте отправителя, получателя и правила сервиса.',TELEGRAM_REJECTED:'Telegram отклонил запрос: проверьте токен, chat_id, запуск бота и права в группе/канале.',TELEGRAM_LIMIT:'Лимит Telegram. Повтор назначен позже.',RESULT_UNKNOWN:'Сервис мог принять уведомление. Проверьте получателя перед повтором.',WORKER_INTERRUPTED:'Сервер перезапущен во время отправки. Результат неизвестен.'}
const date=v=>v?new Date(v).toLocaleString('ru-RU'):'—'
async function run(fn){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
async function loadForms(){forms.value=await props.apiWrite('/api/admin/forms','GET')}
async function loadSettings(){settings.value=await props.apiWrite('/api/admin/forms/settings','GET');toText.value=settings.value.email.to.join('\n');smtpPassword.value='';botToken.value='';clearPassword.value=false;clearToken.value=false}
async function loadMessages(page=1){messages.value=await props.apiWrite('/api/admin/forms/messages?'+new URLSearchParams({page:String(page),status:status.value}),'GET')}
async function reload(){await run(async()=>{await Promise.all([loadForms(),loadSettings(),loadMessages()])})}
function edit(row){draft.value=JSON.parse(JSON.stringify(row||defaultForm));preview.value=false;error.value=''}
async function saveForm(){await run(async()=>{const d=draft.value;await props.apiWrite('/api/admin/forms'+(d.id?'/'+d.id:''),d.id?'PUT':'POST',d);draft.value=null;await loadForms();notice.value='Форма сохранена. Добавьте её секцией на странице.'})}
function addField(){if(draft.value.fields.length>=10)return;let n=1;while(draft.value.fields.some(f=>f.key==='field_'+n))n++;draft.value.fields.push({key:'field_'+n,label:'Новое поле',type:'text',required:false});preview.value=false}
function preset(value){const e=settings.value.email;if(value==='1gb'){Object.assign(e,{mode:'1gb',host:'robots.1gb.ru',port:25,tls:'relay',user:''})}else{Object.assign(e,{mode:'smtp',host:({yandex:'smtp.yandex.ru',mailru:'smtp.mail.ru',gmail:'smtp.gmail.com'})[value]||'',port:465,tls:'implicit'})}}
async function saveSettings(){await run(async()=>{settings.value=await props.apiWrite('/api/admin/forms/settings','PUT',{...settings.value,email:{...settings.value.email,to:toText.value.split(/[\s,;]+/).filter(Boolean)},smtp_password:smtpPassword.value,bot_token:botToken.value,clear_smtp_password:clearPassword.value,clear_bot_token:clearToken.value});toText.value=settings.value.email.to.join('\n');smtpPassword.value='';botToken.value='';clearPassword.value=false;clearToken.value=false;await loadForms();notice.value='Каналы сохранены. Используйте тест отправки, чтобы проверить фактическую доставку.'})}
async function test(channel){await run(async()=>{const r=await props.apiWrite('/api/admin/forms/test','POST',{channel});await loadMessages();notice.value='Тест '+r.number+' поставлен в очередь. Результат — во вкладке «Заявки».'})}
async function openMessage(id){await run(async()=>{message.value=await props.apiWrite('/api/admin/forms/messages/'+id,'GET');retryAck.value=false})}
async function saveMessage(){await run(async()=>{await props.apiWrite('/api/admin/forms/messages/'+message.value.id,'PUT',{status:message.value.status,revision:message.value.revision});message.value=await props.apiWrite('/api/admin/forms/messages/'+message.value.id,'GET');await loadMessages(messages.value.page)})}
async function retry(job){await run(async()=>{await props.apiWrite('/api/admin/forms/deliveries/'+job.id+'/retry','POST',{acknowledge_duplicate:retryAck.value});message.value=await props.apiWrite('/api/admin/forms/messages/'+message.value.id,'GET');retryAck.value=false;notice.value='Повтор поставлен в очередь с текущими сохранёнными настройками канала.'})}
onMounted(reload)
</script>
<template><div class="forms-workspace"><div class="page-title"><div><span class="eyebrow">ОБРАТНАЯ СВЯЗЬ</span><h1>Формы и заявки</h1><p>Конструктор форм, обращения посетителей и доставка уведомлений.</p></div><button class="row-btn" :disabled="busy" @click="reload">Обновить</button></div>
<div class="forms-tabs"><button v-for="(name,key) in {forms:'Формы',messages:'Заявки',settings:'Почта и Telegram'}" :key="key" class="row-btn" :class="{active:tab===key}" @click="tab=key">{{name}}</button></div><p v-if="error" class="alert" role="alert">{{error}}</p><p v-if="notice" class="forms-notice" role="status">{{notice}}</p>
<section v-if="tab==='forms'" class="panel forms-panel"><div class="forms-heading"><h2>Ваши формы</h2><button class="primary-btn" :disabled="busy" @click="edit()">＋ Создать форму</button></div><p>Создайте форму, настройте каналы и добавьте секцию «Форма обратной связи» в редакторе страницы. Так её можно разместить и на главной странице сайта.</p><p v-if="settings&&!settings.enabled" class="forms-help">Приём обращений выключен. Настройте и включите его во вкладке «Почта и Telegram».</p><article v-for="f in forms" :key="f.id" class="forms-card"><div><h3>{{f.title}}</h3><p>{{f.enabled?'Включена':'Выключена'}} · {{f.channels.map(c=>c==='email'?'Email':'Telegram').join(' + ')}} · {{f.ready?'Каналы настроены':'Каналы требуют настройки'}}</p></div><button class="row-btn" :disabled="busy" @click="edit(f)">Редактировать</button></article><p v-if="!forms.length" class="empty">Форм пока нет.</p></section>
<section v-if="tab==='messages'" class="panel forms-panel"><div class="forms-heading"><h2>Заявки: {{messages.total}}</h2><label>Статус<select v-model="status" aria-label="Статус заявки" @change="run(()=>loadMessages())"><option value="">Все</option><option v-for="(name,key) in messageStates" :key="key" :value="key">{{name}}</option></select></label><button class="row-btn" :disabled="busy" @click="run(()=>loadMessages(messages.page))">Обновить заявки</button></div><div class="table-scroll"><table><thead><tr><th>Обращение</th><th>Статус</th><th>Уведомления</th><th></th></tr></thead><tbody><tr v-for="m in messages.rows" :key="m.id"><td><strong>{{m.number}} · {{m.title}}</strong><small>{{date(m.created_at)}}</small></td><td>{{messageStates[m.status]}}</td><td><p v-for="d in m.deliveries" :key="d.channel">{{d.channel==='email'?'Email':'Telegram'}}: {{deliveryStates[d.state]}}</p></td><td><button class="row-btn" :disabled="busy" @click="openMessage(m.id)">Открыть заявку</button></td></tr></tbody></table></div><p v-if="!messages.rows.length" class="empty">Обращений пока нет.</p><div class="forms-pages"><button class="row-btn" :disabled="busy||messages.page<=1" @click="run(()=>loadMessages(messages.page-1))">←</button><span>{{messages.page}} / {{Math.max(1,Math.ceil(messages.total/25))}}</span><button class="row-btn" :disabled="busy||messages.page*25>=messages.total" @click="run(()=>loadMessages(messages.page+1))">→</button></div></section>
<form v-if="tab==='settings'&&settings" @submit.prevent="saveSettings"><fieldset :disabled="busy"><section class="panel forms-panel"><h2>Приём обращений</h2><label class="forms-check"><input v-model="settings.enabled" type="checkbox"> Включить формы и доставку уведомлений</label><p>Заявка сначала сохраняется в NOVA, затем уведомления отправляются в фоне. Статус «Принято сервисом» означает приём SMTP-сервером или Telegram, а не прочтение сообщения.</p><label>Хранить заявки, дней<input v-model.number="settings.retention_days" type="number" min="30" max="365"></label><p>По окончании срока обращения и история доставки удаляются автоматически. Срок жизни резервных копий настраивается отдельно.</p><p v-if="settings.secret_error" class="alert">Не удалось расшифровать секреты. Возможно, изменён ADMIN_API_KEY. Введите пароль и токен заново.</p></section>
<section class="panel forms-panel"><h2>Электронная почта</h2><label class="forms-check"><input v-model="settings.email.enabled" type="checkbox"> Отправлять уведомления на email</label><label>Профиль подключения<select aria-label="Профиль подключения" :value="settings.email.mode==='1gb'?'1gb':'custom'" @change="preset($event.target.value)"><option value="custom">Обычный SMTP</option><option value="1gb">1Gb.ru — отправка из скриптов</option><option value="yandex">Яндекс — SMTP с TLS</option><option value="mailru">Mail.ru — SMTP с TLS</option><option value="gmail">Gmail — SMTP с TLS</option></select></label><div class="forms-grid"><label>Сервер SMTP<input v-model="settings.email.host" maxlength="253" :readonly="settings.email.mode==='1gb'"></label><label>Порт<input v-model.number="settings.email.port" type="number" :readonly="settings.email.mode==='1gb'"></label><label>Защита соединения<select v-model="settings.email.tls" aria-label="Защита SMTP" :disabled="settings.email.mode==='1gb'"><option value="implicit">TLS с начала соединения (обычно 465)</option><option value="starttls">Обязательный STARTTLS (обычно 587)</option><option v-if="settings.email.mode==='1gb'" value="relay">Реле 1Gb.ru, STARTTLS при поддержке</option></select></label><label>Логин SMTP<input v-model="settings.email.user" autocomplete="off" maxlength="254" :readonly="settings.email.mode==='1gb'"></label></div><template v-if="settings.email.mode!=='1gb'"><label>Пароль SMTP / пароль приложения<input v-model="smtpPassword" type="password" autocomplete="new-password" maxlength="1000" :placeholder="settings.smtp_password_set?'Сохранён. Оставьте пустым, чтобы не менять':'Не задан'"></label><label class="forms-check"><input v-model="clearPassword" type="checkbox"> Удалить сохранённый пароль</label></template><label>Адрес отправителя (From)<input v-model="settings.email.from" type="email" maxlength="254" placeholder="forms@your-domain.ru"></label><label>Получатели (до 5), по одному на строке<textarea v-model="toText" rows="3"></textarea></label><p>From должен принадлежать вашему почтовому сервису. Email посетителя ставится в Reply-To, а не подменяет отправителя. Для сервисов с двухфакторным входом обычно нужен пароль приложения или отдельный SMTP-ключ; OAuth в этом релизе не поддерживается.</p><div v-if="settings.email.mode==='1gb'" class="forms-help"><strong>Особенности 1Gb.ru</strong><p>Для скриптов: robots.1gb.ru, порт 25, без авторизации. From — существующий ящик или псевдоним на 1Gb.ru. Почтовые серверы пользовательских ящиков не заменяют этот профиль. Реле может передавать данные без TLS. Используйте его только на разрешённом сервере 1Gb.ru; при необходимости уточните доступ у поддержки.</p></div><p>На VDS для внешнего SMTP может потребоваться открытие порта в поддержке 1Gb.ru. На виртуальном хостинге провайдер отдельно настраивает доступ к внешнему SMTP; сама NOVA требует Node.js и PostgreSQL. SPF/DKIM/DMARC настраиваются у почтового сервиса и в DNS.</p><a href="https://www.1gb.ru/hosting_email.php" target="_blank" rel="noopener noreferrer">Официальная инструкция 1Gb.ru ↗</a><button type="button" class="row-btn" :disabled="busy" @click="test('email')">Отправить тест на email</button></section>
<section class="panel forms-panel"><h2>Telegram</h2><label class="forms-check"><input v-model="settings.telegram.enabled" type="checkbox"> Отправлять уведомления в Telegram</label><label>Токен бота<input v-model="botToken" type="password" autocomplete="new-password" maxlength="150" :placeholder="settings.bot_token_set?'Сохранён. Оставьте пустым, чтобы не менять':'Получите у @BotFather'"></label><label class="forms-check"><input v-model="clearToken" type="checkbox"> Удалить сохранённый токен</label><label>Получатель: chat_id / @имя канала<input v-model="settings.telegram.chat_id" maxlength="40" placeholder="-100…"></label><p>Создайте бота через @BotFather. Для личного чата сначала нажмите у него Start. Для группы добавьте бота и разрешите отправку; для канала выдайте нужные права администратора. Числовой chat_id группы может быть отрицательным. Длинные уведомления сокращаются, полный текст остаётся в заявке.</p><p>С VDS должен быть доступен https://api.telegram.org:443. Ошибки сети и ограничения Telegram видны в истории доставки; ни токен, ни текст обращения не выводятся в журналы API.</p><a href="https://core.telegram.org/bots/api#sendmessage" target="_blank" rel="noopener noreferrer">Документация Telegram ↗</a><button type="button" class="row-btn" :disabled="busy" @click="test('telegram')">Отправить тест в Telegram</button></section><section class="panel forms-panel"><p>Тесты отправляются на последние сохранённые адреса и chat_id. Сначала сохраните настройки. Реальные обращения передаются только в выбранные вами каналы.</p><button class="primary-btn">{{busy?'Сохранение…':'Сохранить каналы'}}</button></section></fieldset></form>
<div v-if="draft" class="modal-backdrop"><div class="modal forms-modal" role="dialog" aria-modal="true" aria-label="Редактор формы"><div class="modal-heading"><h2>{{draft.id?'Редактирование формы':'Новая форма'}}</h2><button aria-label="Закрыть редактор формы" :disabled="busy" @click="draft=null">×</button></div><form @submit.prevent="saveForm"><fieldset :disabled="busy"><label>Название формы<input v-model="draft.title" maxlength="150" required></label><label>Описание формы<textarea v-model="draft.description" maxlength="2000" rows="3"></textarea></label><label class="forms-check"><input v-model="draft.enabled" type="checkbox"> Включить форму</label><div class="forms-grid"><label class="forms-check"><input v-model="draft.channels" type="checkbox" value="email"> Email</label><label class="forms-check"><input v-model="draft.channels" type="checkbox" value="telegram"> Telegram</label></div><h3>Поля</h3><article v-for="(f,index) in draft.fields" :key="index" class="forms-field"><div class="forms-grid"><label>Ключ поля<input v-model="f.key" maxlength="40" required></label><label>Подпись поля<input v-model="f.label" maxlength="100" required></label><label>Тип поля<select v-model="f.type" :aria-label="'Тип поля '+(index+1)"><option v-for="(name,key) in formFieldTypes" :key="key" :value="key">{{name}}</option></select></label><label class="forms-check"><input v-model="f.required" type="checkbox"> Обязательное</label></div><div class="forms-heading"><button type="button" class="row-btn" :disabled="index===0" @click="draft.fields.splice(index-1,0,...draft.fields.splice(index,1))">↑</button><button type="button" class="row-btn" :disabled="index===draft.fields.length-1" @click="draft.fields.splice(index+1,0,...draft.fields.splice(index,1))">↓</button><button type="button" class="row-btn danger" @click="draft.fields.splice(index,1)">Удалить поле</button></div></article><button type="button" class="row-btn" :disabled="draft.fields.length>=10" @click="addField">＋ Добавить поле</button><label>Надпись кнопки<input v-model="draft.button" maxlength="100" required></label><label>Сообщение после отправки<textarea v-model="draft.success" maxlength="1000" rows="2" required></textarea></label><label>Текст согласия<textarea v-model="draft.consent_label" maxlength="1000" rows="2" required></textarea></label><label>Ссылка на политику обработки данных<input v-model="draft.privacy_url" maxlength="2000" placeholder="/privacy"></label><p>Настройте текст согласия и политику под свой сайт и выбранные каналы. Заявки и уведомления могут содержать персональные данные посетителей.</p><button type="button" class="row-btn" @click="preview=!preview">{{preview?'Закрыть предпросмотр':'Предпросмотр формы'}}</button><ContactForm v-if="preview" :preview="draft"/><p v-if="error" class="alert" role="alert">{{error}}</p><button class="primary-btn">Сохранить форму</button></fieldset></form></div></div>
<div v-if="message" class="modal-backdrop"><div class="modal forms-modal" role="dialog" aria-modal="true" aria-label="Карточка заявки"><div class="modal-heading"><h2>{{message.number}} · {{message.snapshot.title}}</h2><button aria-label="Закрыть заявку" :disabled="busy" @click="message=null">×</button></div><p>{{date(message.created_at)}} · {{message.source||'Источник не указан'}}</p><dl class="forms-values"><template v-for="f in message.snapshot.fields" :key="f.key"><dt>{{f.label}}</dt><dd>{{typeof message.values[f.key]==='boolean'?(message.values[f.key]?'Да':'Нет'):message.values[f.key]}}</dd></template></dl><p>Согласие при отправке: {{message.snapshot.consent_label}}</p><p v-if="message.snapshot.privacy_url">Политика: {{message.snapshot.privacy_url}}</p><form @submit.prevent="saveMessage"><label>Статус обращения<select v-model="message.status" aria-label="Статус обращения"><option v-for="(name,key) in messageStates" :key="key" :value="key">{{name}}</option></select></label><button class="primary-btn" :disabled="busy">Сохранить статус</button></form><h3>Уведомления</h3><p>После исправления ошибок обновите карточку. Успешные каналы повторно не отправляются автоматически.</p><article v-for="job in message.deliveries" :key="job.id" class="forms-field"><strong>{{job.channel==='email'?'Email':'Telegram'}} · {{deliveryStates[job.state]}}</strong><p>Попыток: {{job.attempts}} · {{date(job.finished_at||job.started_at)}}</p><p v-if="job.error_code">{{failures[job.error_code]||job.error_code}}</p><button v-if="['failed','uncertain','partial'].includes(job.state)" class="row-btn" :disabled="busy||!retryAck" @click="retry(job)">Повторить с текущими настройками</button></article><label class="forms-check"><input v-model="retryAck" type="checkbox"> Перед повтором я проверил доставку. Повтор может создать дубликат и использует текущих получателей из настроек.</label><p v-if="error" class="alert" role="alert">{{error}}</p><button class="row-btn" :disabled="busy" @click="openMessage(message.id)">Обновить карточку</button></div></div>
</div></template>
<style scoped>
.forms-panel{padding:24px;margin-bottom:20px;display:grid;gap:16px;min-width:0}.forms-panel h2,.forms-panel p,.forms-card h3{margin:0}.forms-panel p,.forms-workspace p{font-size:13px;line-height:1.7;overflow-wrap:anywhere}.forms-workspace label{display:grid;gap:8px;font-size:13px}.forms-workspace input,.forms-workspace textarea,.forms-workspace select{font:inherit;border:1px solid #d3dfd7;border-radius:8px;padding:11px;box-sizing:border-box;width:100%;background:#fff;color:#1c3b2b}.forms-workspace fieldset{border:0;padding:0;margin:0;display:grid;gap:16px;min-width:0}.forms-check{display:flex!important;align-items:flex-start;gap:10px!important;line-height:1.6}.forms-check input{width:auto;flex-shrink:0;margin-top:4px}.forms-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px;min-width:0}.forms-tabs,.forms-heading{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.forms-tabs{margin-bottom:20px}.forms-tabs .active{background:#286b4c;color:white}.forms-card{padding:18px;border:1px solid #d6e2da;border-radius:8px;display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap}.forms-card h3{font-size:16px}.forms-notice,.forms-help{padding:16px;background:#edf6ef;color:#2b5d3a;border-radius:8px}.forms-modal{width:min(950px,100%)}.forms-field{border:1px solid #d5e1d9;padding:16px;border-radius:8px;margin-bottom:14px}.forms-field .forms-heading{margin-top:12px}.forms-workspace a{color:#256a4c}.forms-workspace small{display:block;color:#63786d;margin-top:6px}.forms-pages{display:flex;align-items:center;justify-content:center;gap:18px}.forms-values dt{font-weight:700;margin-top:20px}.forms-values dd{margin:8px 0 0;white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.7}.forms-modal button{margin-top:8px}.forms-workspace button:disabled{opacity:.5;cursor:default}@media(max-width:650px){.forms-grid{grid-template-columns:1fr}.forms-panel{padding:16px}}
</style>
